package com.hostelcheck.backend.controller;
import com.hostelcheck.backend.entity.*;import com.hostelcheck.backend.repository.*;import com.hostelcheck.backend.service.AuthService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class PropertyController {private final PropertyListingRepository properties;private final UserAccountRepository users;private final AuthService auth;public PropertyController(PropertyListingRepository p,UserAccountRepository u,AuthService a){properties=p;users=u;auth=a;}
 @GetMapping("/properties") public List<Map<String,Object>> all(){return properties.findByStatusOrderByCreatedAtDesc("APPROVED").stream().map(this::map).toList();}
 @GetMapping("/properties/{id}") public Map<String,Object> one(@PathVariable Long id){PropertyListing p=properties.findById(id).orElseThrow(()->new IllegalArgumentException("Property not found."));if(!p.getStatus().equals("APPROVED"))throw new IllegalArgumentException("Property not found.");return map(p);}
 @GetMapping("/agent/properties") public List<Map<String,Object>> mine(@RequestHeader(value="X-Auth-Token",required=false)String token){UserAccount u=auth.require(token);if(!u.getRole().equals("House Agent"))throw new IllegalArgumentException("Only house agents can view their listings.");return properties.findByAgentIdOrderByCreatedAtDesc(u.getId()).stream().map(this::map).toList();}
 @PostMapping("/agent/properties") public Map<String,Object> create(@RequestHeader(value="X-Auth-Token",required=false)String token,@RequestBody Map<String,Object>d){UserAccount u=auth.require(token);if(!u.getRole().equals("House Agent"))throw new IllegalArgumentException("Only house agents can submit properties.");PropertyListing p=new PropertyListing();p.setTitle(req(d,"title"));p.setAddress(req(d,"address"));p.setPropertyType(req(d,"propertyType"));try{p.setAnnualRentNaira(Long.parseLong(req(d,"annualRentNaira")));}catch(Exception e){throw new IllegalArgumentException("Enter a valid annual rent amount.");}p.setDescription(AuthService.str(d,"description"));p.setFacilities(AuthService.str(d,"facilities"));p.setPhotoUrls(AuthService.str(d,"photoUrls"));p.setAgentId(u.getId());p.setAgentName(u.getFullName());return map(properties.save(p));}
 private String req(Map<String,Object>d,String k){String v=AuthService.str(d,k);if(v.isBlank())throw new IllegalArgumentException(k+" is required.");return v;}
 private Map<String,Object>map(PropertyListing p){Map<String,Object>m=new LinkedHashMap<>();m.put("id",p.getId());m.put("title",p.getTitle());m.put("address",p.getAddress());m.put("propertyType",p.getPropertyType());m.put("annualRentNaira",p.getAnnualRentNaira());m.put("description",p.getDescription());m.put("facilities",p.getFacilities());m.put("photoUrls",p.getPhotoUrls());m.put("agentId",p.getAgentId());m.put("agentName",p.getAgentName());m.put("status",p.getStatus());m.put("propertyVerified",p.isPropertyVerified());m.put("createdAt",p.getCreatedAt());return m;} }
